import System.Exception;import System.DBNull;import System.Type;import System.ArgumentException;import System.Reflection.*;import java.nio.file.*;import java.util.*;
class CloneInterfaceMemberReflectionProbe {
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static String flag(boolean b){return b?"1":"0";}
 static String kind(Object v){return v==null?"null":v==DBNull.Value?"DBNull":v.getClass().getName();}
 static String method(MethodInfo m){if(m==null)return "~";ParameterInfo p=m.get_ReturnParameter();StringJoiner j=new StringJoiner("|");j.add(m.get_Name());j.add(m.get_DeclaringType().get_FullName());j.add(m.get_ReflectedType().get_FullName());j.add(m.get_ReturnType().get_FullName());j.add(m.ToString());j.add(Integer.toString(m.get_MemberType().get_Value()));
 for(boolean b:new boolean[]{m.get_IsPublic(),m.get_IsPrivate(),m.get_IsFamily(),m.get_IsAssembly(),m.get_IsFamilyAndAssembly(),m.get_IsFamilyOrAssembly(),m.get_IsStatic(),m.get_IsAbstract(),m.get_IsVirtual(),m.get_IsFinal(),m.get_IsSpecialName(),m.get_IsConstructor(),m.get_IsHideBySig()})j.add(flag(b));j.add(Integer.toString(m.get_CallingConvention().get_Value()));for(boolean b:new boolean[]{m.get_IsSecurityCritical(),m.get_IsSecuritySafeCritical(),m.get_IsSecurityTransparent()})j.add(flag(b));j.add(Integer.toString(m.GetMethodImplementationFlags().get_Value()));j.add(flag(m.GetMethodBody()==null));for(boolean b:new boolean[]{m.get_IsGenericMethod(),m.get_IsGenericMethodDefinition(),m.get_IsConstructedGenericMethod(),m.get_ContainsGenericParameters()})j.add(flag(b));j.add(Integer.toString(m.GetGenericArguments().length));j.add(Integer.toString(m.GetParameters().length));j.add(m.GetBaseDefinition().get_Name());j.add(m.GetBaseDefinition().get_DeclaringType().get_FullName());
 j.add(units(p.get_Name()));j.add(Integer.toString(p.get_Position()));j.add(p.get_ParameterType().get_FullName());j.add(flag(p.get_IsOptional()));j.add(flag(p.get_HasDefaultValue()));j.add(kind(p.get_DefaultValue()));j.add(kind(p.get_RawDefaultValue()));for(boolean b:new boolean[]{p.get_IsIn(),p.get_IsOut(),p.get_IsRetval(),p.get_IsLcid()})j.add(flag(b));j.add(Integer.toString(p.get_Attributes().get_Value()));j.add(Integer.toString(p.GetOptionalCustomModifiers().length));j.add(Integer.toString(p.GetRequiredCustomModifiers().length));j.add(p.get_Member().get_Name());j.add(p.ToString());return j.toString();}
 static Type[] types(String p){return switch(p){case "empty"->new Type[0];case "object"->new Type[]{Type.GetType("System.Object")};case "int"->new Type[]{Type.GetType("System.Int32")};case "null"->null;case "nullElement"->new Type[]{null};case "twoObjects"->new Type[]{Type.GetType("System.Object"),Type.GetType("System.Object")};default->throw new AssertionError();};}
 static String result(Type t,String route,String name,BindingFlags flags,Type[] parameters,MemberTypes memberMask){try{Object value=switch(route){case "named"->t.GetMethod(name);case "flagged"->t.GetMethod(name,flags);case "typed"->t.GetMethod(name,parameters);case "flaggedTyped"->t.GetMethod(name,flags,parameters);case "member"->t.GetMember(name);case "flaggedMember"->t.GetMember(name,flags);case "filteredMember"->t.GetMember(name,memberMask,flags);case "members"->t.GetMembers();case "flaggedMembers"->t.GetMembers(flags);case "methods"->t.GetMethods();case "flaggedMethods"->t.GetMethods(flags);case "defaults"->t.GetDefaultMembers();default->throw new AssertionError(route);};if(route.equals("named")||route.equals("flagged")||route.equals("typed")||route.equals("flaggedTyped"))return "OK|method|"+method((MethodInfo)value);StringJoiner j=new StringJoiner(";");for(MemberInfo m:(MemberInfo[])value)j.add(method((MethodInfo)m));return "OK|array|"+j;}catch(Exception e){return "ERR|"+e.getClass().getName()+"|"+units(e.get_Message())+"|"+e.get_HResult()+"|"+units(e instanceof ArgumentException a?a.get_ParamName():null);}}
 public static void main(String[] args)throws java.lang.Exception{Type t=Type.GetType("System.ICloneable");int cases=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);String actual=result(t,p[0],text(p[1]),BindingFlags.FromInt32(Integer.parseInt(p[2])),types(p[3]),MemberTypes.FromInt32(Integer.parseInt(p[4])));if(!actual.equals(p[5]))throw new AssertionError("reflection "+line+" actual="+actual);cases++;}java.lang.System.out.println("PASS ICloneable member reflection cases="+cases+" groups="+cases);}
}
